INSERT INTO patterns (id, phase_id, name, description, recognition_clues, intuition, generic_approach, time_complexity, space_complexity, common_mistakes, mastery_status, sequence_order, created_at, updated_at) VALUES ('a0a00000-0000-0000-0000-000000001501', 'b0a00000-0000-0000-0000-000000000015', 'RECURSION FUNDAMENTALS', 'Mastering basic recursive divisions and mathematical functions.', 'Basic recursive division or math functions.', 'Define base cases first, then trace recursive steps.', '', 'O(2^N)', 'O(N)', '', 'LEARNING', 1, '2026-08-09T00:13:49.355347', '2026-08-09T00:13:49.355347');
