INSERT INTO patterns (id, phase_id, name, description, recognition_clues, intuition, generic_approach, time_complexity, space_complexity, common_mistakes, mastery_status, sequence_order, created_at, updated_at) VALUES ('a0a00000-0000-0000-0000-000000001506', 'b0a00000-0000-0000-0000-000000000015', 'STRING BACKTRACKING', 'Generating permutations or combinations over string characters.', 'Form combinations or choices using string characters.', 'Append char, recurse, then backtrack (delete/truncate length).', 'Modify StringBuilder buffer in-place during recursive steps.', 'O(M^N)', 'O(N)', 'Creating immutable String instances at each recursive depth.', 'NOT_STARTED', 6, '2026-08-12T09:51:27.979479', '2026-08-12T09:51:27.979479');
