INSERT INTO patterns (id, phase_id, name, description, recognition_clues, intuition, generic_approach, time_complexity, space_complexity, common_mistakes, mastery_status, sequence_order, created_at, updated_at) VALUES ('a0a00000-0000-0000-0000-000000001508', 'b0a00000-0000-0000-0000-000000000015', 'PALINDROME PARTITIONING', 'Decomposing string ranges into palindromes recursively.', 'Split string into substrings that are palindromes.', 'Partition range recursively, backtrack if split is invalid.', 'Traverse substrings, validate palindromes, and recurse.', 'O(N * 2^N)', 'O(N)', 'Re-computing palindrome checks repeatedly instead of caching.', 'NOT_STARTED', 8, '2026-08-12T09:51:27.979479', '2026-08-12T09:51:27.979479');
INSERT INTO patterns (id, phase_id, name, description, recognition_clues, intuition, generic_approach, time_complexity, space_complexity, common_mistakes, mastery_status, sequence_order, created_at, updated_at) VALUES ('a0a00000-0000-0000-0000-000000001509', 'b0a00000-0000-0000-0000-000000000015', 'GRID / MATRIX BACKTRACKING', 'DFS backtracking over 2D grids and matrix directions.', 'DFS exploration in 2D grid/matrix spaces.', 'Temporarily mark cell visited (e.g. ''#''), recurse in 4 directions, then restore.', 'Use in-place cell grid replacement or visited boolean matrix.', 'O(4^(R*C))', 'O(R*C)', 'Infinitely looping on cycles or missing restoration steps.', 'NOT_STARTED', 9, '2026-08-12T09:51:27.979479', '2026-08-12T09:51:27.979479');
INSERT INTO patterns (id, phase_id, name, description, recognition_clues, intuition, generic_approach, time_complexity, space_complexity, common_mistakes, mastery_status, sequence_order, created_at, updated_at) VALUES ('a0a00000-0000-0000-0000-000000001510', 'b0a00000-0000-0000-0000-000000000015', 'N-QUEENS', 'Mastering constraint checks across diagonals and columns.', 'Place elements avoiding threats in multiple dimensions.', 'Track row, column, and diagonal state constraints.', 'Utilize boolean checks or bit arrays to check threats.', 'O(N!)', 'O(N)', 'Inefficient O(N) threat checks at each board row placement.', 'NOT_STARTED', 10, '2026-08-12T09:51:27.979479', '2026-08-12T09:51:27.979479');
INSERT INTO patterns (id, phase_id, name, description, recognition_clues, intuition, generic_approach, time_complexity, space_complexity, common_mistakes, mastery_status, sequence_order, created_at, updated_at) VALUES ('a0a00000-0000-0000-0000-000000001511', 'b0a00000-0000-0000-0000-000000000015', 'SUDOKU / CONSTRAINT SATISFACTION', 'Resolving complex local constraints recursively.', 'Fill grid values checking local block/column constraints.', 'Try all values (1-9) for empty cells and backtrack on collisions.', 'Test digits recursively and backtrack if sudoku fails rules.', 'O(9^(R*C))', 'O(R*C)', 'Attempting to fill already solved cells.', 'NOT_STARTED', 11, '2026-08-12T09:51:27.979479', '2026-08-12T09:51:27.979479');
