INSERT INTO patterns (id, phase_id, name, description, recognition_clues, intuition, generic_approach, time_complexity, space_complexity, common_mistakes, mastery_status, sequence_order, created_at, updated_at) VALUES ('a0a00000-0000-0000-0000-000000001704', 'b0a00000-0000-0000-0000-000000000017', 'GRID / 2D DP', 'Optimizing path or boundary routes in grid coordinate systems.', 'Exploration and paths in 2D coordinate spaces.', 'Propagate solutions from top/left cells dynamically.', 'Set bounds and populate grid cells layer-by-layer.', 'O(R * C)', 'O(C) to O(R*C)', 'Confusing indices or ignoring obstacles limits.', 'NOT_STARTED', 4, '2026-08-12T13:13:07.302365', '2026-08-12T13:13:07.302365');
INSERT INTO patterns (id, phase_id, name, description, recognition_clues, intuition, generic_approach, time_complexity, space_complexity, common_mistakes, mastery_status, sequence_order, created_at, updated_at) VALUES ('a0a00000-0000-0000-0000-000000001705', 'b0a00000-0000-0000-0000-000000000017', 'KNAPSACK — 0/1 KNAPSACK', 'Item selections with constraints allowing single choice.', 'Item selections with constraints where each item can be chosen at most once.', 'Iterate items backwards over capacity dimension to prevent re-use.', 'Update 1D capacity array from right-to-left.', 'O(N * W)', 'O(W)', 'Iterating forwards and accidentally reusing elements.', 'NOT_STARTED', 5, '2026-08-12T13:13:07.302365', '2026-08-12T13:13:07.302365');
INSERT INTO patterns (id, phase_id, name, description, recognition_clues, intuition, generic_approach, time_complexity, space_complexity, common_mistakes, mastery_status, sequence_order, created_at, updated_at) VALUES ('a0a00000-0000-0000-0000-000000001706', 'b0a00000-0000-0000-0000-000000000017', 'UNBOUNDED KNAPSACK', 'Constraint selections allowing infinite duplicate items.', 'Item selections with capacity constraints allowing infinite duplicates.', 'Iterate capacity forwards to allow duplicate choices of items.', 'Update 1D capacity array from left-to-right.', 'O(N * W)', 'O(W)', 'Iterating backwards, restricting elements to single use.', 'NOT_STARTED', 6, '2026-08-12T13:13:07.302365', '2026-08-12T13:13:07.302365');
INSERT INTO patterns (id, phase_id, name, description, recognition_clues, intuition, generic_approach, time_complexity, space_complexity, common_mistakes, mastery_status, sequence_order, created_at, updated_at) VALUES ('a0a00000-0000-0000-0000-000000001707', 'b0a00000-0000-0000-0000-000000000017', 'SUBSET SUM / PARTITION DP', 'Partitioning arrays to match subset targets.', 'Dividing array into sets matching specific target sums.', 'Treat subsets as 0/1 Knapsack constraints.', 'Find subset target sum first, then run subset checks.', 'O(N * Sum)', 'O(Sum)', 'Processing partition arrays without checking odd totals.', 'NOT_STARTED', 7, '2026-08-12T13:13:07.302365', '2026-08-12T13:13:07.302365');
INSERT INTO patterns (id, phase_id, name, description, recognition_clues, intuition, generic_approach, time_complexity, space_complexity, common_mistakes, mastery_status, sequence_order, created_at, updated_at) VALUES ('a0a00000-0000-0000-0000-000000001708', 'b0a00000-0000-0000-0000-000000000017', 'STRING DP — LCS', 'Identifying common sequence configurations between multiple strings.', 'Finding common subsequences or alignments between two strings.', 'Compare character matches at index pointers dynamically.', 'Construct a 2D match grid checking matching chars.', 'O(M * N)', 'O(min(M,N))', 'Failing to handle off-by-one indexing of match matrix.', 'NOT_STARTED', 8, '2026-08-12T13:13:07.302365', '2026-08-12T13:13:07.302365');
INSERT INTO patterns (id, phase_id, name, description, recognition_clues, intuition, generic_approach, time_complexity, space_complexity, common_mistakes, mastery_status, sequence_order, created_at, updated_at) VALUES ('a0a00000-0000-0000-0000-000000001709', 'b0a00000-0000-0000-0000-000000000017', 'EDIT DISTANCE', 'Resolving edit operations between distinct sequences.', 'Minimum transformations (inserts, deletes, replacements) between strings.', 'Minimum of diagonal, top, and left cell transitions.', 'Compute edits on match matrix dynamically.', 'O(M * N)', 'O(min(M,N))', 'Overlooking base operations for empty string steps.', 'NOT_STARTED', 9, '2026-08-12T13:13:07.302365', '2026-08-12T13:13:07.302365');
INSERT INTO patterns (id, phase_id, name, description, recognition_clues, intuition, generic_approach, time_complexity, space_complexity, common_mistakes, mastery_status, sequence_order, created_at, updated_at) VALUES ('a0a00000-0000-0000-0000-000000001710', 'b0a00000-0000-0000-0000-000000000017', 'PALINDROME DP', 'Subrange computations checking boundary equalities.', 'Analyzing palindromic substrings or partitions.', 'Interval expansion checks or boolean interval lookup maps.', 'Loop over range sizes, verifying boundary matches.', 'O(N^2)', 'O(N^2)', 'Incorrect expansion direction bounds.', 'NOT_STARTED', 10, '2026-08-12T13:13:07.302365', '2026-08-12T13:13:07.302365');
INSERT INTO patterns (id, phase_id, name, description, recognition_clues, intuition, generic_approach, time_complexity, space_complexity, common_mistakes, mastery_status, sequence_order, created_at, updated_at) VALUES ('a0a00000-0000-0000-0000-000000001711', 'b0a00000-0000-0000-0000-000000000017', 'LIS — LONGEST INCREASING SUBSEQUENCE', 'Strictly increasing subarray length tracking.', 'Longest strictly increasing sequence of array elements.', 'Compare index with all previous indices or use binary search limits.', 'Use DP array search or binary search tail tracking.', 'O(N log N)', 'O(N)', 'Failing to keep values strictly increasing.', 'NOT_STARTED', 11, '2026-08-12T13:13:07.302365', '2026-08-12T13:13:07.302365');
INSERT INTO patterns (id, phase_id, name, description, recognition_clues, intuition, generic_approach, time_complexity, space_complexity, common_mistakes, mastery_status, sequence_order, created_at, updated_at) VALUES ('a0a00000-0000-0000-0000-000000001712', 'b0a00000-0000-0000-0000-000000000017', 'STOCK DP', 'State machines tracking transaction and cooldown variables.', 'Deciding buy, sell, or cooldown states to maximize profit.', 'Track state variables for holding or not holding stock.', 'Compute hold, sell, and cooldown state steps dynamically.', 'O(N)', 'O(1)', 'Ignoring cooling down constraints or max limit bounds.', 'NOT_STARTED', 12, '2026-08-12T13:13:07.302365', '2026-08-12T13:13:07.302365');
INSERT INTO patterns (id, phase_id, name, description, recognition_clues, intuition, generic_approach, time_complexity, space_complexity, common_mistakes, mastery_status, sequence_order, created_at, updated_at) VALUES ('a0a00000-0000-0000-0000-000000001713', 'b0a00000-0000-0000-0000-000000000017', 'INTERVAL DP', 'Subrange optimal updates by breaking ranges.', 'Solving problems on contiguous subranges/intervals.', 'Divide range at split point k and combine subinterval answers.', 'Iterate sizes, compute split bounds and minimize cuts.', 'O(N^3)', 'O(N^2)', 'Incorrect base initializes for sizes = 1 or 2.', 'NOT_STARTED', 13, '2026-08-12T13:13:07.302365', '2026-08-12T13:13:07.302365');
INSERT INTO patterns (id, phase_id, name, description, recognition_clues, intuition, generic_approach, time_complexity, space_complexity, common_mistakes, mastery_status, sequence_order, created_at, updated_at) VALUES ('a0a00000-0000-0000-0000-000000001714', 'b0a00000-0000-0000-0000-000000000017', 'DP ON GRAPHS / TREES', 'Subtree structural optimizations.', 'Tree traversals with choice selections.', 'Return choice pairs (include root vs exclude root) post-order.', 'Perform bottom-up DFS recursive state updates.', 'O(N)', 'O(N)', 'Including direct children values when parent is robbed.', 'NOT_STARTED', 14, '2026-08-12T13:13:07.302365', '2026-08-12T13:13:07.302365');
INSERT INTO patterns (id, phase_id, name, description, recognition_clues, intuition, generic_approach, time_complexity, space_complexity, common_mistakes, mastery_status, sequence_order, created_at, updated_at) VALUES ('a0a00000-0000-0000-0000-000000001715', 'b0a00000-0000-0000-0000-000000000017', 'ADVANCED DP — OPTIONAL', 'Highly complex multi-dimensional wildcard matching and range splits.', 'Complex matching strings, regular expressions, or range splits.', 'Define double-indexed states checking wildcards or split bounds.', 'Run multi-pointer coordinate matches.', 'O(M * N)', 'O(M * N)', 'Mismating star wildcards matching zero elements.', 'NOT_STARTED', 15, '2026-08-12T13:13:07.302365', '2026-08-12T13:13:07.302365');
