-- Squashed Flyway baseline migration V1__baseline.sql

DROP TABLE IF EXISTS revisions CASCADE;
DROP TABLE IF EXISTS mistakes CASCADE;
DROP TABLE IF EXISTS problem_details CASCADE;
DROP TABLE IF EXISTS problems CASCADE;
DROP TABLE IF EXISTS patterns CASCADE;
DROP TABLE IF EXISTS phases CASCADE;

CREATE TABLE phases (
    id UUID PRIMARY KEY,
    phase_number INT NOT NULL UNIQUE,
    topic VARCHAR(100) NOT NULL,
    priority VARCHAR(50) NOT NULL,
    status VARCHAR(50) NOT NULL,
    sequence_order INT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_phases_status ON phases(status);

CREATE TABLE patterns (
    id UUID PRIMARY KEY,
    phase_id UUID NOT NULL,
    name VARCHAR(255) NOT NULL,
    description TEXT NOT NULL,
    recognition_clues TEXT,
    intuition TEXT,
    generic_approach TEXT,
    time_complexity VARCHAR(50),
    space_complexity VARCHAR(50),
    common_mistakes TEXT,
    mastery_status VARCHAR(50) NOT NULL,
    sequence_order INT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_patterns_phase FOREIGN KEY (phase_id) REFERENCES phases(id) ON DELETE CASCADE
);

CREATE INDEX idx_patterns_phase_id ON patterns(phase_id);
CREATE INDEX idx_patterns_mastery ON patterns(mastery_status);

CREATE TABLE problems (
    id UUID PRIMARY KEY,
    pattern_id UUID NOT NULL,
    leetcode_number INT NOT NULL,
    name VARCHAR(200) NOT NULL,
    url VARCHAR(500) NOT NULL,
    difficulty VARCHAR(50) NOT NULL,
    status VARCHAR(50) NOT NULL,
    date_solved DATE NOT NULL,
    time_taken_minutes INT,
    attempts_count INT NOT NULL DEFAULT 1,
    independent_solve BOOLEAN NOT NULL DEFAULT TRUE,
    leetcode_verified BOOLEAN DEFAULT FALSE,
    purpose VARCHAR(500),
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_problems_pattern FOREIGN KEY (pattern_id) REFERENCES patterns(id) ON DELETE CASCADE
);

CREATE INDEX idx_problems_pattern_id ON problems(pattern_id);
CREATE INDEX idx_problems_status ON problems(status);
CREATE INDEX idx_problems_difficulty ON problems(difficulty);

CREATE TABLE problem_details (
    problem_id UUID PRIMARY KEY,
    intuition TEXT NOT NULL,
    approach TEXT NOT NULL,
    code_snippet TEXT NOT NULL,
    complexity_analysis TEXT,
    what_i_learned TEXT,
    CONSTRAINT fk_details_problem FOREIGN KEY (problem_id) REFERENCES problems(id) ON DELETE CASCADE
);

CREATE TABLE mistakes (
    id UUID PRIMARY KEY,
    problem_id UUID NOT NULL,
    pattern_id UUID NOT NULL,
    description TEXT NOT NULL,
    correct_understanding TEXT NOT NULL,
    date_created DATE NOT NULL,
    is_resolved BOOLEAN NOT NULL DEFAULT FALSE,
    revision_count INT NOT NULL DEFAULT 0,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_mistakes_problem FOREIGN KEY (problem_id) REFERENCES problems(id) ON DELETE CASCADE,
    CONSTRAINT fk_mistakes_pattern FOREIGN KEY (pattern_id) REFERENCES patterns(id) ON DELETE RESTRICT
);

CREATE INDEX idx_mistakes_problem_id ON mistakes(problem_id);
CREATE INDEX idx_mistakes_pattern_id ON mistakes(pattern_id);
CREATE INDEX idx_mistakes_is_resolved ON mistakes(is_resolved);

CREATE TABLE revisions (
    id UUID PRIMARY KEY,
    problem_id UUID NOT NULL,
    revision_number INT NOT NULL,
    due_date DATE NOT NULL,
    status VARCHAR(50) NOT NULL,
    completed_date DATE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_revisions_problem FOREIGN KEY (problem_id) REFERENCES problems(id) ON DELETE CASCADE
);

CREATE INDEX idx_revisions_problem_id ON revisions(problem_id);
CREATE INDEX idx_revisions_due_date_status ON revisions(due_date, status);


